from rdflib import Graph

g = Graph()
g.parse("/app/university_graph.ttl", format="turtle")

# Check Math201 active students
query = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema/>

SELECT ?student (COUNT(DISTINCT ?student) AS ?cnt)
WHERE {
  ?student a uni:Person ;
           uni:isEnrolledIn uni:Math201 ;
           uni:hasEnrollmentDate ?enrollDate .
  FILTER(?enrollDate <= "2025-08-16"^^xsd:date)
  OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
  FILTER(!BOUND(?gradDate) || ?gradDate > "2025-08-17"^^xsd:date)
}
GROUP BY ?student
"""
for row in g.query(query):
    print(f"Student: {row.student}, Count: {row.cnt}")

# Total count
query2 = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema/>

SELECT (COUNT(DISTINCT ?student) AS ?cnt)
WHERE {
  ?student a uni:Person ;
           uni:isEnrolledIn uni:Math201 ;
           uni:hasEnrollmentDate ?enrollDate .
  FILTER(?enrollDate <= "2025-08-16"^^xsd:date)
  OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
  FILTER(!BOUND(?gradDate) || ?gradDate > "2025-08-17"^^xsd:date)
}
"""
for row in g.query(query2):
    print(f"Total active Math201 students: {row.cnt}")
